import sys

def main():
    d = sys.stdin.read().split()
    n = int(d[0])
    pts = sorted((int(d[1 + 2 * i]), int(d[2 + 2 * i])) for i in range(n))

    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    col = all(cross(pts[0], pts[1], p) == 0 for p in pts[2:]) if n > 2 else True
    if n == 1:
        hull = pts[:]
    else:
        lower = []
        for p in pts:
            while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
                lower.pop()
            lower.append(p)
        upper = []
        for p in reversed(pts):
            while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
                upper.pop()
            upper.append(p)
        hull = lower[:-1] + upper[:-1]
    out = ['YES' if col else 'NO', str(len(hull))]
    out += ['%d %d' % p for p in hull]
    print('\n'.join(out))

