n = int(d[0])
P = [(int(d[1 + 2 * i]), int(d[2 + 2 * i])) for i in range(n)]

def cross(o, a, b):
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

col = True
for i in range(n):
    for j in range(i + 1, n):
        for k in range(j + 1, n):
            if cross(P[i], P[j], P[k]) != 0:
                col = False

def on_seg(p, a, b):
    return cross(a, b, p) == 0 and min(a[0], b[0]) <= p[0] <= max(a[0], b[0]) and min(a[1], b[1]) <= p[1] <= max(a[1], b[1])

def in_tri(p, a, b, c):
    s1, s2, s3 = cross(a, b, p), cross(b, c, p), cross(c, a, p)
    neg = s1 < 0 or s2 < 0 or s3 < 0
    pos = s1 > 0 or s2 > 0 or s3 > 0
    return not (neg and pos)

verts = []
for i in range(n):
    others = [P[j] for j in range(n) if j != i]
    inside = False
    for a in range(len(others)):
        for b in range(a + 1, len(others)):
            if on_seg(P[i], others[a], others[b]):
                inside = True
            for c in range(b + 1, len(others)):
                if cross(others[a], others[b], others[c]) != 0 and in_tri(P[i], others[a], others[b], others[c]):
